WITH RECURSIVE MenuCTE AS (
SELECT id, pid
FROM sys_menu
/* 只查询目录和菜单, 不查询按钮*/
WHERE id = #{menuId}

    AND menu_type_cd != '1002003'

UNION ALL
SELECT sm.id, sm.pid
FROM sys_menu sm
JOIN MenuCTE cte ON sm.pid = cte.id
)
SELECT id
FROM MenuCTE;

WITH RECURSIVE MenuCTE AS ( SELECT id, pid FROM sys_menu WHERE id IN
#{id}
AND del_flag = 0 UNION ALL SELECT sm.id, sm.pid FROM sys_menu sm JOIN MenuCTE cte ON sm.pid = cte.id WHERE sm.del_flag = 0 ) SELECT id FROM MenuCTE;

mapper.update:
UPDATE sys_menu
SET del_flag = 1
WHERE id IN

    #{id}

;
